/**
 * Story 374 (consistency-08) — the one reader of an activity's start.
 *
 * An activity's time of day lives in `metadata.start` as an ISO instant: the Health Connect
 * convention since story 250, the manual and calendar one since story 299, and the old Strava rows'
 * since story 324's migration. Four private copies used to parse it, with two normalizations, and
 * one had already drifted — coaching timed only the Strava rows for months. A change to the
 * convention is now made here.
 */

/** The stored start instant; null when the metadata has none or it cannot be read. */
export function activityStartInstant(metadata: string | null | undefined): Temporal.Instant | null {
    if (!metadata) return null;
    let start: unknown;
    try {
        start = (JSON.parse(metadata) as { start?: unknown }).start;
    } catch {
        return null;
    }
    if (typeof start !== 'string') return null;
    try {
        return Temporal.Instant.from(start);
    } catch {
        return null;
    }
}

/** `HH:MM` of the start in [timeZone]; empty string when there is none. */
export function activityStartLocalTime(metadata: string | null | undefined, timeZone: string): string {
    const start = activityStartInstant(metadata)?.toZonedDateTimeISO(timeZone);
    if (!start) return '';
    return `${String(start.hour).padStart(2, '0')}:${String(start.minute).padStart(2, '0')}`;
}

/** The start's own local date (YYYY-MM-DD) in [timeZone]; null when there is none. */
export function activityStartLocalDate(metadata: string | null | undefined, timeZone: string): string | null {
    return activityStartInstant(metadata)?.toZonedDateTimeISO(timeZone).toPlainDate().toString() ?? null;
}
